import { styled, View } from '@tamagui/web';

import { useItemContext } from './ItemContext';
import type { ItemPartAttributes } from './types';
import { ariaAndDataAttributes } from '../../helpers/ariaAndDataAttributes';
import { cx, cxx } from '../../helpers/composeClassNames';
import { pickWebPressHandlers } from '../../helpers/pickAttributes';

export type ItemDragHandleProps = {
	/**
	 * Shows the grip as unavailable, for a row that cannot move right now.
	 */
	disabled?: boolean;
} & ItemPartAttributes;

// generated by scripts/generate-frame-values.mts from @rocket.chat/fuselage-tokens, do not edit

const itemDragHandleFrame = {
	display: 'flex',
	flexDirection: 'row',
	alignItems: 'center',
	flexShrink: 0,
	minWidth: 'auto',
	minHeight: 'auto',
	render: 'span',
	justifyContent: 'center',
	flexGrow: 0,
	flexBasis: 'auto',
	width: '1rem',
	height: '1.25rem',
	touchAction: 'none',
	cursor: {
		default: 'grab',
		press: 'grabbing',
	},
	color: {
		'default': 'var(--rcx-item-color-font-secondary, var(--rcx-color-font-secondary-info, #6c737a))',
		'group-hover/item': 'var(--rcx-item-color-font-highlighted, var(--rcx-color-font-titles-labels, #1f2329))',
	},
} as const;

const itemDragHandleLooks = {
	dragging: {
		cursor: 'grabbing',
	},
	disabled: {
		cursor: 'not-allowed',
		color: 'var(--rcx-item-color-font-disabled, var(--rcx-color-font-disabled, #cbced1))',
	},
} as const;

// end of generated

// Declared where it renders: zero-runtime only erases a `styled()` whose every use is in its own module
const ItemDragHandleFrame = styled(View, {
	...itemDragHandleFrame,
	variants: { look: itemDragHandleLooks },
});

const lookOf = (disabled: boolean | undefined, dragging: boolean) => {
	if (disabled) return 'disabled';
	return dragging ? 'dragging' : undefined;
};

/**
 * The grip that starts dragging an `Item`, placed as its last slot. The row itself carries the keyboard move,
 * so the grip is hidden from assistive technologies and never takes focus.
 */
const ItemDragHandle = (props: ItemDragHandleProps) => {
	const { disabled, className, children } = props;
	const { dragging } = useItemContext();

	return (
		<ItemDragHandleFrame
			look={lookOf(disabled, dragging)}
			className={cx(cxx('rcx-item__drag-handle')({ disabled: !!disabled }), className)}
			render={
				<span
					aria-hidden='true'
					{...ariaAndDataAttributes(props)}
					{...pickWebPressHandlers(props)}
					ref={props.ref}
					id={props.id}
					title={props.title}
					role={props.role}
					tabIndex={props.tabIndex}
				/>
			}
		>
			<svg width='10' height='16' viewBox='0 0 10 16' fill='currentColor'>
				<circle cx='2' cy='3' r='1.5' />
				<circle cx='8' cy='3' r='1.5' />
				<circle cx='2' cy='8' r='1.5' />
				<circle cx='8' cy='8' r='1.5' />
				<circle cx='2' cy='13' r='1.5' />
				<circle cx='8' cy='13' r='1.5' />
			</svg>
			{children}
		</ItemDragHandleFrame>
	);
};

export default ItemDragHandle;
